def increment(state, node):
    p, n = state
    p = dict(p)
    p[node] = p.get(node, 0) + 1
    return p, n


def decrement(state, node):
    p, n = state
    n = dict(n)
    n[node] = n.get(node, 0) + 1
    return p, n


def value(state):
    p, n = state
    return sum(p.values()) - sum(n.values())


